(function(){'use strict';var root=document.getElementById('k20CatalogV2');if(!root||root.dataset.ready==='1')return;root.dataset.ready='1';var source=document.getElementById('k20ProductSource'),topSearch=document.getElementById('k20TopSearch'),sideSearch=document.getElementById('k20SideSearch'),miniSearch=document.getElementById('k20MiniSearch'),stockOnly=document.getElementById('k20StockOnly'),priceRange=document.getElementById('k20PriceRange'),priceLabel=document.getElementById('k20PriceLabel'),sortSelect=document.getElementById('k20SortSelect'),noResults=document.getElementById('k20NoResults'),filterPanel=document.getElementById('k20FilterPanel'),filterBackdrop=document.getElementById('k20FilterBackdrop'),toast=document.getElementById('k20Toast');var compare=[],activeKeyword='',products=[],maxPrice=0,initialOrder=[];function txt(el){return el?(el.textContent||'').replace(/s+/g,' ').trim():''}
function normalize(s){return(s||'').replace(/[ي]/g,'ی').replace(/[ك]/g,'ک').replace(/u200c/g,' ').replace(/s+/g,' ').trim().toLowerCase()}
function toLatinDigits(s){var p='۰۱۲۳۴۵۶۷۸۹';return(s||'').replace(/[۰-۹]/g,function(d){return String(p.indexOf(d))}).replace(/[٬,]/g,'')}
function getPrice(li){var a=li.querySelectorAll('.price .amount,.price bdi'),raw=a.length?txt(a[a.length-1]):txt(li.querySelector('.price')),n=parseInt(toLatinDigits(raw).replace(/[^0-9]/g,''),10);return isNaN(n)?0:n}
function getTitle(li){return txt(li.querySelector('.woocommerce-loop-product__title'))||txt(li.querySelector('h2'))||txt(li)}
function getLink(li){var a=li.querySelector('a.woocommerce-LoopProduct-link,a[href]');return a?a.href:'/shop/'}
function getImage(li){var im=li.querySelector('img');return im?(im.currentSrc||im.src):''}
function getPriceText(li){return txt(li.querySelector('.price'))||'قیمت را در صفحه محصول ببینید'}
function isOut(li){return li.classList.contains('outofstock')||normalize(txt(li)).indexOf('ناموجود')>-1}
function notify(m){toast.textContent=m;toast.classList.add('show');setTimeout(function(){toast.classList.remove('show')},1600)}
function refreshProducts(){products=Array.prototype.slice.call(source.querySelectorAll('ul.products li.product'));initialOrder=products.slice();maxPrice=0;products.forEach(function(li,index){li.dataset.k20Index=String(index);var p=getPrice(li);if(p>maxPrice)maxPrice=p;if(!li.querySelector('.k20-card-tools')){var tools=document.createElement('div');tools.className='k20-card-tools';var fav=document.createElement('button');fav.type='button';fav.innerHTML='♡';fav.setAttribute('aria-label','علاقه مندی');var cmp=document.createElement('button');cmp.type='button';cmp.innerHTML='⚖';cmp.setAttribute('aria-label','افزودن به مقایسه');tools.appendChild(fav);tools.appendChild(cmp);li.appendChild(tools);fav.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();fav.classList.toggle('active');fav.innerHTML=fav.classList.contains('active')?'♥':'♡';notify('علاقه مندی به روز شد')});cmp.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();toggleCompare(li,cmp)})}li.addEventListener('mouseenter',function(){updateDetail(li)});li.addEventListener('click',function(e){if(e.target.closest('.k20-card-tools'))return;updateDetail(li)})});priceRange.max=String(maxPrice||100);priceRange.value=String(maxPrice||100);priceLabel.textContent=maxPrice?('تا '+maxPrice.toLocaleString('fa-IR')+' تومان'):'همه قیمت ها';if(products.length)updateDetail(products[0]);applyFilters()}
function applyFilters(){var q=normalize(sideSearch.value||topSearch.value||miniSearch.value||''),cat=normalize(activeKeyword),only=stockOnly.checked,max=Number(priceRange.value||maxPrice||0),visible=0;products.forEach(function(li){var hay=normalize(getTitle(li)+' '+txt(li)),ok=(!q||hay.indexOf(q)>-1)&&(!cat||hay.indexOf(cat)>-1)&&(!only||!isOut(li))&&(!maxPrice||getPrice(li)===0||getPrice(li)<=max);li.style.display=ok?'':'none';if(ok)visible++});noResults.hidden=visible!==0}
function sortProducts(){var ul=source.querySelector('ul.products');if(!ul)return;var arr=products.slice(),mode=sortSelect.value;if(mode==='name')arr.sort(function(a,b){return getTitle(a).localeCompare(getTitle(b),'fa')});if(mode==='price-asc')arr.sort(function(a,b){return getPrice(a)-getPrice(b)});if(mode==='price-desc')arr.sort(function(a,b){return getPrice(b)-getPrice(a)});if(mode==='default')arr=initialOrder.slice();arr.forEach(function(li){ul.appendChild(li)});products=arr;applyFilters()}
function syncSearch(v){topSearch.value=v;sideSearch.value=v;miniSearch.value=v;applyFilters()}
function updateDetail(li){var title=getTitle(li),price=getPriceText(li),link=getLink(li),image=getImage(li),stock=isOut(li)?'ناموجود':'موجود';document.getElementById('k20DetailTitle').textContent=title;document.getElementById('k20DetailPrice').textContent=price;var media=document.getElementById('k20DetailMedia');media.innerHTML=image?('<img decoding="async" src="'+image.replace(/"/g,'&quot;')+'" alt="'+title.replace(/"/g,'&quot;')+'">'):'</p>
<div class="k20-detail-placeholder">بدون تصویر</div>
<p>';document.getElementById('k20DetailLink').href=link;document.getElementById('k20DetailActions').textContent=stock==='موجود'?'● موجود در فروشگاه':'● وضعیت موجودی را بررسی کنید';var rows=document.getElementById('k20SpecRows');rows.innerHTML='';[['نام محصول',title],['وضعیت',stock],['قیمت',price],['دسته بندی','اطلاعات صفحه محصول'],['اطلاعات کامل','مشاهده صفحه محصول']].forEach(function(row){var d=document.createElement('div'),s=document.createElement('span'),b=document.createElement('b');s.textContent=row[0];b.textContent=row[1];d.appendChild(s);d.appendChild(b);rows.appendChild(d)})}
function toggleCompare(li,btn){var idx=compare.indexOf(li);if(idx>-1){compare.splice(idx,1);btn.classList.remove('active');notify('از مقایسه حذف شد')}else{if(compare.length>=2){notify('برای این نما حداکثر دو محصول انتخاب کنید');return}compare.push(li);btn.classList.add('active');notify('به مقایسه اضافه شد')}renderCompare()}
function renderCompare(){var box=document.getElementById('k20CompareMini');if(!compare.length){box.innerHTML='</p>
<p>دو محصول را برای مقایسه انتخاب کنید.</p>
<p>';return}var html='';compare.forEach(function(li){html+='</p>
<div class="k20-compare-row">'+(getImage(li)?'<img decoding="async" src="'+getImage(li).replace(/"/g,'&quot;')+'" alt="">':'<span></span>')+'<b>'+getTitle(li)+'</b></div>
<p>'});if(compare.length===2)html+='</p>
<div class="k20-compare-checks"><span>✓ قیمت</span><span>✓ موجودی</span><span>✓ مشخصات</span><span>✓ کاربرد</span></div>
<p>';box.innerHTML=html}
function setCategory(keyword,button){activeKeyword=keyword||'';document.querySelectorAll('#k20CatalogV2 .k20-category-strip button').forEach(function(b){b.classList.remove('active')});if(button)button.classList.add('active');applyFilters()}[topSearch,sideSearch,miniSearch].forEach(function(input){input.addEventListener('input',function(){syncSearch(this.value)})});stockOnly.addEventListener('change',applyFilters);priceRange.addEventListener('input',function(){var v=Number(this.value||0);priceLabel.textContent=maxPrice?('تا '+v.toLocaleString('fa-IR')+' تومان'):'همه قیمت ها';applyFilters()});sortSelect.addEventListener('change',sortProducts);document.querySelectorAll('#k20CatalogV2 input[name=k20cat]').forEach(function(r){r.addEventListener('change',function(){setCategory(this.value,null)})});document.querySelectorAll('#k20CatalogV2 .k20-category-strip button').forEach(function(b){b.addEventListener('click',function(){setCategory(this.getAttribute('data-keyword')||'',this)})});document.getElementById('k20ClearFilters').addEventListener('click',function(){activeKeyword='';syncSearch('');stockOnly.checked=!1;sortSelect.value='default';priceRange.value=String(maxPrice||100);priceLabel.textContent=maxPrice?('تا '+maxPrice.toLocaleString('fa-IR')+' تومان'):'همه قیمت ها';document.querySelectorAll('#k20CatalogV2 input[name=k20cat]').forEach(function(r){r.checked=r.value===''});document.querySelectorAll('#k20CatalogV2 .k20-category-strip button').forEach(function(b){b.classList.remove('active')});sortProducts()});document.getElementById('k20ResetView').addEventListener('click',function(){document.getElementById('k20ClearFilters').click()});document.getElementById('k20ShowProducts').addEventListener('click',function(){source.scrollIntoView({behavior:'smooth',block:'center'})});function openFilter(){filterPanel.classList.add('open');filterBackdrop.classList.add('open')}function closeFilter(){filterPanel.classList.remove('open');filterBackdrop.classList.remove('open')}document.getElementById('k20MobileFilter').addEventListener('click',openFilter);filterBackdrop.addEventListener('click',closeFilter);document.querySelectorAll('#k20CatalogV2 [data-focus]').forEach(function(b){b.addEventListener('click',function(){var t=this.getAttribute('data-focus');if(t==='search'){topSearch.focus()}else if(t==='compare'){document.getElementById('k20ComparePanel').scrollIntoView({behavior:'smooth',block:'center'})}else if(t==='specs'||t==='technical'){document.getElementById('k20SpecPanel').scrollIntoView({behavior:'smooth',block:'center'})}})});document.querySelectorAll('#k20CatalogV2 [data-nav]').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('#k20CatalogV2 [data-nav]').forEach(function(x){x.classList.remove('active')});this.classList.add('active');var n=this.getAttribute('data-nav');if(n==='filters'){if(window.innerWidth<=760)openFilter();else filterPanel.scrollIntoView({behavior:'smooth',block:'center'})}else if(n==='compare'){document.getElementById('k20ComparePanel').scrollIntoView({behavior:'smooth',block:'center'})}else if(n==='product'){document.getElementById('k20DetailPanel').scrollIntoView({behavior:'smooth',block:'center'})}else if(n==='technical'){document.getElementById('k20SpecPanel').scrollIntoView({behavior:'smooth',block:'center'})}else{document.getElementById('k20AppShell').scrollIntoView({behavior:'smooth',block:'center'})}})});document.getElementById('k20HeaderFav').addEventListener('click',function(){notify('علاقه مندی ها از کارت محصولات قابل مدیریت است')});function initWhenReady(){var count=source.querySelectorAll('ul.products li.product').length;if(count){refreshProducts();window.__K20CatalogV2={ready:!0,productCount:products.length,applyFilters:applyFilters};return!0}return!1}
if(!initWhenReady()){var observer=new MutationObserver(function(){if(initWhenReady())observer.disconnect()});observer.observe(source,{childList:!0,subtree:!0});setTimeout(function(){if(!window.__K20CatalogV2){window.__K20CatalogV2={ready:!1,productCount:0}}},3500)}})()
